meanings.gt_sql:
SELECT atom_id AS id FROM atom WHERE molecule_id IN (SELECT molecule_id FROM molecule WHERE label = '+')
UNION
SELECT bond_id AS id FROM bond WHERE molecule_id IN (SELECT molecule_id FROM molecule WHERE label = '+');

turns.sql:
SELECT atom_id AS id, 'atom' AS type FROM atom WHERE molecule_id IN (SELECT molecule_id FROM molecule WHERE label = '+')
UNION ALL
SELECT bond_id AS id, 'bond' AS type FROM bond WHERE molecule_id IN (SELECT molecule_id FROM molecule WHERE label = '+');

SELECT atom_id AS id, 'atom' AS entity_type FROM atom a JOIN molecule m ON a.molecule_id = m.molecule_id WHERE m.label = '+'
UNION ALL
SELECT bond_id AS id, 'bond' AS entity_type FROM bond b JOIN molecule m ON b.molecule_id = m.molecule_id WHERE m.label = '+';

SELECT atom_id, element
FROM atom
WHERE molecule_id = 'TR000' AND element IN ('c', 'h');
